// Generated by toolbox — the animation timeline.
// Do not edit by hand: change the SkSL Shader node and export again.

export const TIMELINE = {
  fps: 60,
  ticksPerFrame: 1000,
  durationTicks: 300000,
  durationSec: 5,
} as const;

export const CANVAS = { width: 512, height: 512 } as const;

// animation: "baked" — every animated uniform is evaluated inside the SkSL from
// iTime (effect.ts). Per frame the shader needs only the clock, the canvas
// size and the static uniforms. width/height are the canvas size in points.
export function sampleUniforms(seconds: number, width: number, height: number) {
  "worklet";
  return {
    iResolution: [width, height, 1],
    iTime: seconds,
    octaves: 4, // static (channel row)
    persistence: 0.5, // static (channel row)
    lacunarity: 2, // static (channel row)
    drift_y: 0, // static (channel row)
    c0: [0.0392156862745098,0.058823529411764705,0.17254901960784313,1], // static (channel row)
    c1: [0.23921568627450981,0.35294117647058826,0.996078431372549,1], // static (channel row)
    c3: [1,0.8901960784313725,0.7607843137254902,1], // static (channel row)
  };
}
